import{initHumanBehavior,humanSchedule,effectiveHumanTime,updateHumans,validateHumanBehavior}from './human-behavior.js';
import{worldAccess,connectWorldHuman}from './world-profile.js';
import{localEncounters}from './encounters.js';
import{mix,syncContext}from './world.js';import{changeArea}from './social.js';
export const FACILITIES={home:{label:'가정집',medical:true,group:false},street:{label:'거리',medical:false,group:false},shelter:{label:'보호소',medical:true,group:true},petshop:{label:'판매점',medical:true,group:false},clinic:{label:'동물병원',medical:true,group:false}};
const score=(s,id,salt)=>20+mix(`${s.seed}:${id}`,salt)%76;
export function ensureHuman(s,id,role){s.humans??=[];let p=s.humans.find(h=>h.id===id);if(!p){p={id,role,name:{guardian:'함께 사는 사람',shelter:'돌보는 직원',shop:'판매점 돌봄 직원',rescuer:'구조하는 사람',vet:'수의사'}[role]||'돌보는 사람',care:score(s,id,901),money:score(s,id,902),time:score(s,id,903),knowledge:score(s,id,904),bond:0,area:s.areaId,decisions:[]};s.humans.push(p)}connectWorldHuman(s,p);initHumanBehavior(s,p);return p;}
export function initPeopleWorld(s){s.environmentModel??={version:1,facility:s.home==='family'?'home':s.home==='shelter'?'shelter':'street',area:s.areaId,access:{},route:null,used:{},nextReview:s.day+120+mix(s.seed,905)%180};if(s.environmentModel.area!==s.areaId){s.environmentModel.area=s.areaId;s.environmentModel.candidate=null;s.environmentModel.placementAttempts=0;delete s.environmentModel.nextPlacement;delete s.environmentModel.shopUntil;s.environmentModel.facility=s.home==='family'?'home':s.home==='shelter'?'shelter':'street'}const e=s.environmentModel;if(e.visit&&s.day>=e.visit.returnDay)delete e.visit;if(s.home!=='street'){s.caregiverId??='carer-'+s.areaId;const h=ensureHuman(s,s.caregiverId,e.facility==='petshop'?'shop':s.home==='family'?'guardian':'shelter');h.area=s.areaId;h.bond=s.familyBond}ensureHuman(s,'vet-'+s.country.id,'vet');for(const h of s.humans)initHumanBehavior(s,h);const w=s.worldModel;const human=s.home!=='street'&&!s.story.lost?s.humans.find(h=>h.id===s.caregiverId&&h.area===s.areaId):null;const support=human?(w.care*.55+human.care*.25+effectiveHumanTime(human,s.day)*.2):w.care;e.access={food:Math.round(s.home==='street'?w.resource:w.resource*.65+support*.35),water:Math.min(100,Math.round(support+(s.home==='family'?15:0))),medical:s.home==='street'?Math.max(0,w.care-45):Math.round((support+(human?.money??50))/2)};e.access=worldAccess(s,e.access);e.dailyCare={day:s.day,feeding:human?human.id:null,availableTime:human?Math.round(effectiveHumanTime(human,s.day)):0,humanActivity:human?(humanSchedule(human,s.day).working?(human.role==='guardian'?'work':'care-shift'):'rest'):null,attention:Math.round(support),medical:e.access.medical};return e;}
export function currentFacility(s){const e=s.environmentModel;return e?.visit&&s.day<e.visit.returnDay?'clinic':e?.facility|| (s.home==='family'?'home':s.home==='shelter'?'shelter':'street');}
export function clinicVisit(s,reason){const e=initPeopleWorld(s);e.visit={facility:'clinic',day:s.day,returnDay:s.day+1,reason,actor:'vet-'+s.country.id};}
export function clinicalAccess(s){initPeopleWorld(s);const h=s.humans.find(h=>h.id===s.caregiverId);return !s.story.lost&&s.home!=='street'&&s.environmentModel.access.medical>=30?{available:true,human:h}: {available:false,human:h};}
export function peopleStep(s,{log,remember}){updateHumans(s);const e=initPeopleWorld(s);const stamp=(id,text,story)=>{log(s,id,text);if(story)s.log.at(-1).storyId=story};
// Placement is a human process. A dog's refusal to enter a carrier does not decide adoption.
if(s.home!=='family'&&!s.story.lost&&s.day>=90&&localEncounters(s)>=3&&!s.story.adoptionReview&&s.day>=(e.nextPlacement||0)&&!s.medical.episode){e.placementAttempts=(e.placementAttempts||0)+1;const id='applicant:'+s.areaId+':'+e.placementAttempts;const human=ensureHuman(s,id,'guardian');human.name='입양을 알아보는 사람';e.candidate=id;e.nextPlacement=s.day+120;const arc={id:'placement:'+id,kind:'placement',stage:'assessment',start:s.day,next:s.day+7,actor:id,area:s.areaId};s.storylines??=[];s.storylines.push(arc);s.story.adoptionReview={day:arc.next,area:s.areaId,actor:id,storyId:arc.id};stamp('placement-visit',e.facility==='petshop'?'방문자가 직원에게 돌봄 방법을 묻고 내 움직임을 살핀다. 며칠 뒤 다시 찾아오기로 하고 오늘은 돌아갔다.':'여러 번 찾아온 사람이 돌보는 사람과 먹이, 쉬는 시간, 함께 살 공간에 대해 이야기를 나눈다. 오늘은 익숙한 자리에서 그대로 잔다.',arc.id);}
if(e.shopUntil&&s.day>=e.shopUntil&&e.facility==='petshop'){delete e.shopUntil;e.facility='shelter';e.route='shelter-adoption';stamp('shop-transfer','오랫동안 지내던 판매점에서 다른 돌봄 시설로 이동했다. 직원이 먹이 기록과 담요를 함께 넘긴다. 새 방에서 물그릇부터 확인한다.','placement:'+s.areaId);}
if(s.home==='shelter'&&s.day>=56&&s.day<120&&!e.used.shop&&mix(s.seed,906)%6===0){e.used.shop=true;e.facility='petshop';e.route='sale';e.shopUntil=s.day+60+mix(s.seed,907)%60;s.caregiverId='shop-carer-'+s.areaId;ensureHuman(s,s.caregiverId,'shop');e.access.food=Math.max(e.access.food,55);stamp('shop-arrival','사람이 이동장을 들고 나간 뒤 유리문이 있는 돌봄 공간에 도착했다. 직원이 물그릇과 잠자리를 챙기고, 문 바깥으로 여러 발걸음이 오간다.','placement:'+s.areaId);}
if(s.home==='street'&&s.day>=100&&!s.story.lost&&!e.used.rescue&&(s.health<65||s.needs.strain>1||s.worldModel.care<35)&&mix(s.seed+s.day,908)%10000<12){e.used.rescue=true;const story='rescue:'+s.areaId;s.storylines??=[];s.storylines.push({id:story,kind:'rescue',start:s.day,stage:'approach',actor:'rescuer-'+s.country.id,next:s.day+4,area:s.areaId});ensureHuman(s,'rescuer-'+s.country.id,'rescuer');stamp('rescue-approach','물과 먹이를 놓던 사람이 며칠째 내 상태를 살핀다. 오늘은 안전한 이동 공간을 곁에 두고 조금 떨어져 기다린다.',story);}
for(const arc of s.storylines||[]){if(arc.kind!=='rescue'||arc.stage!=='approach'||s.day<arc.next)continue;if(s.areaId!==arc.area||s.home!=='street'||s.story.lost){arc.stage='closed';continue}arc.stage='shelter';arc.end=s.day;s.home='shelter';changeArea(s,'rescue');syncContext(s);s.caregiverId='rescue-carer-'+s.areaId;e.facility='shelter';e.route='rescue-adoption';initPeopleWorld(s);stamp('rescued-shelter','사람의 도움으로 이동 공간에 들어갔다. 차가 멈춘 뒤 보호시설의 조용한 방에 새 물과 담요가 놓였다. 아직 낯설지만 바람과 비를 피할 수 있다.',arc.id);remember(s,'rescued');}
if(s.day>=e.nextReview){e.nextReview=s.day+240+mix(s.seed+s.day,909)%240;const h=s.humans.find(h=>h.id===s.caregiverId);if(s.home==='family'&&h&&!s.story.lost){if(h.time<35&&h.money<40&&!e.used.rehome){e.used.rehome=true;e.rehomeFrom=s.caregiverId;e.rehomeAt=s.day+21;e.rehomeKind=mix(s.seed,910)%2?'guardian':'shelter';stamp('guardian-change-planned','사람들의 생활이 바뀌어 돌봄 시간이 줄었다. 다른 사람이 여러 번 찾아와 내 물건과 생활공간을 살핀다. 오늘도 같은 잠자리에서 쉰다.','rehome:'+s.areaId);h.decisions.push({day:s.day,kind:'care-transfer'})}else{h.bond=Math.min(100,h.bond+3)}}}
if(e.rehomeAt&&s.day>=e.rehomeAt&&s.home==='family'&&!s.story.lost&&(!e.rehomeFrom||e.rehomeFrom===s.caregiverId)&&!s.medical.episode&&!s.clinical?.active){delete e.rehomeAt;const story='rehome:'+s.areaId;if(e.rehomeKind==='shelter'){s.home='shelter';changeArea(s,'re-entry');e.route='shelter-adoption';s.caregiverId='shelter-carer-'+s.areaId;syncContext(s);stamp('shelter-return','사람이 내 담요를 함께 보냈다. 보호시설의 다른 방에서 물과 잠자리를 다시 살핀다. 예전 사람은 문 밖으로 나갔고, 돌보는 직원이 곁에서 시간을 보낸다.',story)}else{changeArea(s,'guardian-change');s.caregiverId='guardian-'+s.areaId;s.familyBond=15;s.story.settleAt=s.day+14;syncContext(s);stamp('guardian-changed','몇 번 만났던 사람과 함께 다른 집에 왔다. 익숙한 담요는 있지만 문과 그릇의 위치는 다르다. 새로운 사람의 걸음과 돌봄 시간이 하루씩 쌓인다.',story)}initPeopleWorld(s);remember(s,'care-transfer');}
}
export function validatePeople(s){if(s.humans&&(!Array.isArray(s.humans)||!s.humans.every(h=>typeof h.id==='string'&&typeof h.role==='string'&&['care','money','time','knowledge','bond'].every(k=>Number.isFinite(h[k])))))throw Error('손상된 인간 개체 기록');for(const h of s.humans||[])validateHumanBehavior(h,s.day);if(s.environmentModel&&(!['home','street','shelter','petshop','clinic'].includes(s.environmentModel.facility)||!s.environmentModel.access))throw Error('손상된 환경 기록');}
